import { formatCurrency } from '../lib/money.js';

export const TIMEOUT_MS = 3000;

/** Handles webhooks requests. */
export function handleWebhooks(request) {
  const amount = request.amountCents ?? 0;
  return { route: '/webhooks', timeoutMs: TIMEOUT_MS, amount: formatCurrency(amount) };
}

